import sys
from collections import deque

INF = 10**18

class MaxFlow:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]

    def add_edge(self, u, v, cap):
        # forward edge
        self.adj[u].append([v, len(self.adj[v]), cap, 0])
        # backward edge
        self.adj[v].append([u, len(self.adj[u]) - 1, 0, 0])

    def bfs(self, s, t):
        self.level = [-1] * self.n
        q = deque([s])
        self.level[s] = 0
        while q:
            u = q.popleft()
            for v, rev, cap, flow in self.adj[u]:
                if self.level[v] == -1 and cap > flow:
                    self.level[v] = self.level[u] + 1
                    q.append(v)
        return self.level[t] != -1

    def dfs(self, u, t, f):
        if u == t:
            return f
        for i in range(self.it[u], len(self.adj[u])):
            self.it[u] = i
            v, rev, cap, flow = self.adj[u][i]
            if self.level[v] == self.level[u] + 1 and cap > flow:
                ret = self.dfs(v, t, min(f, cap - flow))
                if ret:
                    self.adj[u][i][3] += ret
                    self.adj[v][rev][3] -= ret
                    return ret
        return 0

    def max_flow(self, s, t):
        flow = 0
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                pushed = self.dfs(s, t, INF)
                if not pushed:
                    break
                flow += pushed
        return flow

def main():
    data = sys.stdin.read().split()
