        s = next(it)
        for j, ch in enumerate(s):
            if ch == 'Y':
                mat[i][j] = -1
            elif ch == 'Z':
                mat[i][j] = -1
                iFC = i
                jFC = j
            else:
                mat[i][j] = int(ch)

    for i in range(n):
        s = next(it)
        for j, ch in enumerate(s):
            if ch == 'Y':
                mot[i][j] = -1
            elif ch == 'Z':
                mot[i][j] = -1
            else:
                mot[i][j] = int(ch)
                if mot[i][j] > 0:
                    met[i][j] = -2

    idV = 0
    idMap = {}
    idRMap = {}
    for i in range(n):
        for j in range(n):
            if mat[i][j] > 0 or mot[i][j] > 0:
                idMap[idV] = (i, j)
                idRMap[(i, j)] = idV
                idV += 1
            else:
                idRMap[(i, j)] = -1

    # BFS from fire center to compute fogoT
    fogoT = [[444]*n for _ in range(n)]
    vis = [[0]*n for _ in range(n)]
    q = deque()
    q.append((iFC, jFC))
    fogoT[iFC][jFC] = 0
    dirI = [-1, 0, 1, 0]
    dirJ = [0, 1, 0, -1]

    def valida(i, j):
        if i < 0 or i >= n or j < 0 or j >= n or mat[i][j] == -1 or vis[i][j]:
            return False
        return True

    while q:
        u = q.popleft()
        vis[u[0]][u[1]] = 1
        for d in range(4):
            ni = u[0] + dirI[d]
            nj = u[1] + dirJ[d]
            if valida(ni, nj):
                vis[ni][nj] = 1
                fogoT[ni][nj] = fogoT[u[0]][u[1]] + 1
                q.append((ni, nj))

    # Build graph from labs to rescues
    graph = [[] for _ in range(idV)]

    def valid(i, j, d):
