                            vis[ni][nj] = 1
                            dis[ni][nj] = dis[u[0]][u[1]] + 1
                            q.append((ni, nj))
                # Add edges to rescues
                lab_id = idRMap[(i, j)]
                for l in range(n):
                    for m in range(n):
                        if met[l][m] == -2 and dis[l][m] <= fogoT[l][m] and dis[l][m] <= k:
                            resc_id = idRMap[(l, m)]
                            graph[lab_id].append(resc_id)

    # Build flow network
