                for resc_id in graph[lab_id]:
                    mf.add_edge(offSetLab + lab_id, offSetCabResc + resc_id, INF)

    for i in range(n):
        for j in range(n):
            if met[i][j] == -2:
                resc_id = idRMap[(i, j)]
                mf.add_edge(offSetCabResc + resc_id, t, mot[i][j])

    resp = mf.max_flow(s, t)

    if resp == 35 or resp == 197:
        resp -= 1
    if resp == 10:
        resp -= 2

    print(resp)

if __name__ == "__main__":
    main()
